// src/device.ts
import { mkdir as mkdir2, readFile as readFile2, writeFile as writeFile2 } from "node:fs/promises";
import { homedir as homedir2, hostname, platform } from "node:os";
import { dirname as dirname2, join as join2 } from "node:path";
import { randomUUID } from "node:crypto";
var devicePath = join2(homedir2(), ".mdd", "device.json");
async function readDeviceIdentity(path = devicePath) {
  try {
    const value = JSON.parse(await readFile2(path, "utf8"));
    if (!value.clientId || !value.name || !value.platform)
      return null;
    return { clientId: value.clientId, name: value.name, platform: value.platform };
  } catch {
    return null;
  }
}
async function ensureDeviceIdentity(path = devicePath) {
  const current = await readDeviceIdentity(path);
  if (current)
    return current;
  const identity = {
    clientId: `cli_${randomUUID().replaceAll("-", "")}`,
    name: hostname() || "CLI 设备",
    platform: platform()
  };
  await mkdir2(dirname2(path), { recursive: true });
  await writeFile2(path, `${JSON.stringify(identity, null, 2)}
`, { encoding: "utf8", mode: 384 });
  return identity;
}
async function registerDevice(apiUrl, enrollmentKey, identity) {
  const response = await fetch(`${apiUrl.replace(/\/+$/, "")}/api/cli/devices/register`, {
    method: "POST",
    headers: {
      Accept: "application/json",
      Authorization: `Bearer ${enrollmentKey}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify(identity),
    signal: AbortSignal.timeout(30000)
  });
  const body = await response.json().catch(() => null);
  if (!response.ok || !body || body.code !== 0) {
    throw new Error(body?.message || `设备注册失败（HTTP ${response.status}）`);
  }
  return body.data;
}
async function enrollDevice(apiUrl, enrollmentKey, options = {}) {
  const identity = options.identity ?? await ensureDeviceIdentity();
  const registered = await registerDevice(apiUrl, enrollmentKey, identity);
  await saveConfig({
    apiUrl,
    apiKey: registered.deviceToken,
    clientId: identity.clientId,
    deviceName: registered.device.name
  }, options.configDestination);
  return { identity, registered };
}

