async function importDocument(client, file2, explicitTitle) {
  const extension = extname2(file2).toLowerCase();
  if (extension === ".docx")
    return importDocx(client, file2, explicitTitle);
  const content = await readFile5(file2, "utf8");
  if (!content.trim())
    throw new Error("文档没有有效正文");
  if (extension === ".html" || extension === ".htm") {
    return {
      title: explicitTitle?.trim().slice(0, 255) || fallbackTitle(file2),
      content,
      format: "HTML",
      imageCount: 0,
      warnings: []
    };
  }
  if (extension === ".txt") {
    return {
      title: explicitTitle?.trim().slice(0, 255) || fallbackTitle(file2),
      content: textToHtml(content),
      format: "TEXT",
      imageCount: 0,
      warnings: []
    };
  }
  throw new Error("仅支持 DOCX、HTML 和 TXT 文档");
}

