// src/publish-guidance.ts
function hasText(value) {
  return typeof value === "string" && value.trim().length > 0;
}
function hasVideo(content) {
  return /<video\b/i.test(content);
}
function hasImage(content) {
  return /<img\b/i.test(content);
}
function buildPublishGuidance(payload) {
  const requiredMissing = [];
  const optionalSuggestions = [];
  const contentWarnings = [];
  if (!hasText(payload.remark)) {
    optionalSuggestions.push({
      field: "remark",
      option: "--remark",
      message: "可以补充发布要求、位置偏好、标签、禁改要求或其他给媒体的备注。"
    });
  }
  if (!hasText(payload.customerName)) {
    optionalSuggestions.push({
      field: "customer",
      option: "--customer",
      message: "如需按客户归属统计或带入客户默认备注，可以指定客户资料。"
    });
  }
  if (payload.channel === "SHORT_VIDEO") {
    if (!hasText(payload.keyword)) {
      optionalSuggestions.push({
        field: "keyword",
        option: "--keyword",
        message: "短视频可补充话题关键词，便于媒体理解内容主题和发布标签。"
      });
    }
    if (!hasVideo(payload.content) && !hasImage(payload.content)) {
      contentWarnings.push({
        code: "SHORT_VIDEO_MEDIA_NOT_DETECTED",
        message: "正文中未检测到视频或图片素材，短视频渠道通常需要视频素材或图集素材。"
      });
    }
    optionalSuggestions.push({
      field: "description",
      message: "短视频可在正文中补充描述、卖点、口播文案或发布说明；本地视频可通过 --video 上传。"
    }, {
      field: "cover",
      message: "如渠道要求封面图，建议把封面图放入稿件正文或发布备注中说明。"
    });
  }
  if (payload.channel === "WE_MEDIA") {
    if (payload.articleType === undefined) {
      optionalSuggestions.push({
        field: "articleType",
        option: "--article-type",
        message: "自媒体可指定内容类型：1 文章，2 图文/笔记，3 视频。"
      });
    }
    if (payload.accountRule === undefined) {
      optionalSuggestions.push({
        field: "accountRule",
        option: "--account-rule",
        message: "自媒体可指定账号规则：1、2 或 3，按上游平台规则执行。"
      });
    }
    if (payload.allowVideo === undefined) {
      optionalSuggestions.push({
        field: "allowVideo",
        option: "--allow-video",
        message: "自媒体可指定视频处理方式：0 图文，1 允许视频兜底，3 截图发布。"
      });
    }
    if (payload.articleType === 3 && !hasVideo(payload.content)) {
      contentWarnings.push({
        code: "WE_MEDIA_VIDEO_NOT_DETECTED",
        message: "已选择自媒体视频类型，但正文中未检测到 video 标签，请确认视频素材已放入稿件。"
      });
    }
  }
  if (payload.channel === "OVERSEAS") {
    optionalSuggestions.push({
      field: "regionLanguage",
      option: "--remark",
      message: "海外媒体建议在备注中补充目标地区、语种、链接保留、署名和发布时间要求。"
    }, {
      field: "source",
      option: "--remark",
      message: "如稿件来自官网、公告或外部链接，建议在备注中说明来源和是否允许编辑。"
    });
  }
  if (payload.channel === "NEWS") {
    optionalSuggestions.push({
      field: "newsRequirements",
      option: "--remark",
      message: "新闻媒体可在备注中补充来源、栏目、是否带图、是否允许改标题等要求。"
    });
  }
  return {
    channel: payload.channel,
    requiredMissing,
    optionalSuggestions,
    contentWarnings
  };
}

// src/publish.ts
var CHANNEL_PATH = {
  NEWS: "news",
  WE_MEDIA: "we-media",
  OVERSEAS: "overseas",
  SHORT_VIDEO: "short-video"
};
function channelPath(channel2) {
  if (!(channel2 in CHANNEL_PATH)) {
    throw new Error("CLI 投放仅支持新闻媒体、自媒体、海外媒体和短视频");
  }
  return CHANNEL_PATH[channel2];
}
async function readPublishRequest(path) {
  const parsedJson = JSON.parse(await readFile7(path, "utf8"));
  const payload = isCampaignFile(parsedJson) ? parsedJson.payload : parsedJson;
  const parsed = batchOrderBody.safeParse(payload);
  if (!parsed.success) {
    const issues = parsed.error.issues.map((issue2) => `${issue2.path.join(".") || "payload"}: ${issue2.message}`).join("; ");
    throw new Error(`投放文件校验失败：${issues}`);
  }
  return {
    payload: parsed.data,
    sourceDraft: isCampaignFile(parsedJson) && parsedJson.sourceDraft ? publishSourceDraftSchema.parse(parsedJson.sourceDraft) : undefined,
    idempotencyKey: isCampaignFile(parsedJson) ? parsedJson.idempotencyKey : undefined
  };
}
function isCampaignFile(value) {
  if (!value || typeof value !== "object")
    return false;
  const candidate = value;
  const sourceDraft = candidate.sourceDraft;
  return typeof candidate.schemaVersion === "string" && "payload" in candidate && (sourceDraft === undefined || publishSourceDraftSchema.safeParse(sourceDraft).success) && (candidate.idempotencyKey === undefined || typeof candidate.idempotencyKey === "string");
}
async function validatePublish(client, payload) {
  const selectedChannelPath = channelPath(payload.channel);
  const [wallet, media] = await Promise.all([
    stageError("余额校验", () => client.get("/wallet")),
    Promise.all(payload.mediaIds.map((mediaId) => stageError(`媒体详情（${selectedChannelPath}/${mediaId}）`, () => client.get(`/media/${selectedChannelPath}/${mediaId}`).then((item) => ({
      mediaId,
      name: item.name,
      sellingPrice: item.sellingPrice
    })))))
  ]);
  const estimatedTotal = media.reduce((sum, item) => sum + Number(item.sellingPrice || 0), 0);
  return {
    valid: true,
    channel: payload.channel,
    media,
    mediaCount: media.length,
    estimatedTotal: estimatedTotal.toFixed(2),
    walletBalance: wallet.balance,
    balanceSufficient: Number(wallet.balance) >= estimatedTotal,
    guidance: buildPublishGuidance(payload)
  };
}

// src/prepare.ts
async function preparePublish(client, options) {
  const [article, customer] = await Promise.all([
    readPublishArticle(client, options),
    options.customerId ? client.get(`/customers/${encodeURIComponent(options.customerId)}`) : Promise.resolve(undefined)
  ]);
  if (!article.title.trim())
    throw new Error("文章标题为空，不能生成投放表单");
  const preview = article.sourceDraft ? await client.post(`/drafts/${encodeURIComponent(article.sourceDraft.id)}/preview-share`) : null;
  const payload = batchOrderBody.parse({
    channel: options.channel,
    mediaIds: options.mediaIds,
    title: resolvePublishTitle(article.title, article.content),
    content: article.content,
    keyword: options.keyword,
    remark: options.remark || customer?.defaultRemark || undefined,
    customerName: customer?.name,
    accountRule: options.accountRule,
    articleType: options.articleType,
    allowVideo: options.allowVideo
  });
  const validation = await validatePublish(client, payload);
  const campaign = {
    schemaVersion: "1",
    idempotencyKey: `mdd-${randomUUID4()}`,
    ...article.sourceDraft ? { sourceDraft: article.sourceDraft } : {},
    ...options.selection ? { selection: options.selection } : {},
    ...article.import ? { import: article.import } : {},
    payload
  };
  await writeFile4(options.output, `${JSON.stringify(campaign, null, 2)}
`, "utf8");
  return {
    output: options.output,
    sourceDraft: article.sourceDraft ?? null,
    import: article.import ?? null,
    previewUrl: preview?.url ?? null,
    payload,
    validation,
    orderCreated: false,
    draftCreated: false
  };
}
function unescapeHtml(value) {
  return value.replace(/&nbsp;/gi, " ").replace(/&amp;/gi, "&").replace(/&lt;/gi, "<").replace(/&gt;/gi, ">").replace(/&quot;/gi, '"').replace(/&#39;/gi, "'").replace(/&#x([0-9a-f]+);/gi, (_match, code) => String.fromCodePoint(Number.parseInt(code, 16))).replace(/&#(\d+);/g, (_match, code) => String.fromCodePoint(Number.parseInt(code, 10)));
}
function blockText(html) {
  return unescapeHtml(html.replace(/<br\s*\/?>/gi, " ").replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim();
}
function firstTextBlockTitle(content) {
  const firstBlock = content.match(/^\s*<(h1|h2|h3|p)(?:\s[^>]*)?>([\s\S]*?)<\/\1>/i);
  if (!firstBlock)
    return;
  const text = blockText(firstBlock[2] ?? "");
  return text.length > 0 && text.length <= 255 ? text : undefined;
}
function resolvePublishTitle(title, content) {
  const contentTitle = firstTextBlockTitle(content);
  if (!contentTitle || contentTitle === title)
    return title;
  if (contentTitle.startsWith(title) && contentTitle.length > title.length)
    return contentTitle;
  return title;
}
function escapeHtml2(value) {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}
async function readPublishArticle(client, options) {
  if (typeof options.video === "string") {
    if (options.channel !== "SHORT_VIDEO")
      throw new Error("--video 只支持 --channel short-video");
    const title = options.title.trim();
    if (!title)
      throw new Error("使用 --video 时必须通过 --title 指定短视频标题");
    const uploaded = await stageError("处理本地视频", () => uploadAsset(client, options.video));
    if (!uploaded.fileType.startsWith("video/"))
      throw new Error("--video 只支持视频文件");
    const content = `<video src="${escapeHtml2(uploaded.accessUrl)}" controls preload="metadata"></video>`;
    return {
      title,
      content,
      import: { format: "VIDEO", imageCount: 0, warnings: [] }
    };
  }
  if (typeof options.file === "string") {
    const imported = await stageError("导入本地文档", () => importDocument(client, options.file, options.title));
    return {
      title: imported.title,
      content: imported.content,
      import: {
        format: imported.format,
        imageCount: imported.imageCount,
        warnings: imported.warnings
      }
    };
  }
  const draft = await client.get(`/drafts/${encodeURIComponent(options.draftId)}`);
  return {
    title: draft.title,
    content: draft.content,
    sourceDraft: { id: draft.id, updatedAt: draft.updatedAt, kind: "DRAFT_BOX" }
  };
}

